import type { ReactNode } from 'react';
import Link from 'next/link';

export type Locale = 'en' | 'es' | 'pt';

type Block =
  | { type: 'p'; text: string }
  | { type: 'h2'; text: string }
  | { type: 'h3'; text: string }
  | { type: 'ul'; items: string[] };

const LINK_TARGETS: Record<string, Record<Locale, string>> = {
  'salmon-website-sot-privacy-en': { en: '/privacy', es: '/es/privacy', pt: '/pt/privacy' },
  'salmon-website-sot-privacy-es': { en: '/privacy', es: '/es/privacy', pt: '/pt/privacy' },
  'salmon-website-sot-privacy-pt': { en: '/privacy', es: '/es/privacy', pt: '/pt/privacy' },
  'salmon-website-sot-terms-en': { en: '/terms', es: '/es/terms', pt: '/pt/terms' },
  'salmon-website-sot-terms-es': { en: '/terms', es: '/es/terms', pt: '/pt/terms' },
  'salmon-website-sot-terms-pt': { en: '/terms', es: '/es/terms', pt: '/pt/terms' },
};

const INLINE_PATTERN =
  /\*\*([^*]+)\*\*|`([^`]+)`|\[\[([\w-]+)\|([^\]]+)\]\]|([\w.+-]+@[\w-]+\.[\w.-]+)/g;

function renderInline(text: string, locale: Locale, keyPrefix: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let i = 0;
  INLINE_PATTERN.lastIndex = 0;
  while ((match = INLINE_PATTERN.exec(text))) {
    if (match.index > lastIndex) nodes.push(text.slice(lastIndex, match.index));
    const [, bold, code, linkTarget, linkLabel, email] = match;
    if (bold !== undefined) {
      nodes.push(
        <strong key={`${keyPrefix}-${i++}`} className="text-text-primary">
          {bold}
        </strong>
      );
    } else if (code !== undefined) {
      nodes.push(code);
    } else if (linkTarget !== undefined) {
      const href = LINK_TARGETS[linkTarget]?.[locale] ?? '#';
      nodes.push(
        <Link key={`${keyPrefix}-${i++}`} href={href} className="text-accent hover:text-accent/80">
          {linkLabel}
        </Link>
      );
    } else if (email !== undefined) {
      nodes.push(
        <a key={`${keyPrefix}-${i++}`} href={`mailto:${email}`} className="text-accent hover:text-accent/80">
          {email}
        </a>
      );
    }
    lastIndex = INLINE_PATTERN.lastIndex;
  }
  if (lastIndex < text.length) nodes.push(text.slice(lastIndex));
  return nodes;
}

export function LegalBody({ blocks, locale }: { blocks: Block[]; locale: Locale }) {
  return (
    <>
      {blocks.map((block, idx) => {
        const key = `block-${idx}`;
        if (block.type === 'h2') {
          return (
            <h2 key={key} className="text-xl font-semibold text-text-primary mt-8">
              {block.text}
            </h2>
          );
        }
        if (block.type === 'h3') {
          return (
            <h3 key={key} className="text-lg font-semibold text-text-primary mt-6">
              {block.text}
            </h3>
          );
        }
        if (block.type === 'ul') {
          return (
            <ul key={key} className="list-disc pl-6 space-y-2">
              {block.items.map((item, i) => (
                <li key={i}>{renderInline(item, locale, `${key}-li-${i}`)}</li>
              ))}
            </ul>
          );
        }
        return <p key={key}>{renderInline(block.text, locale, key)}</p>;
      })}
    </>
  );
}

